science_education:
{
  "education_concept": "从“参观”走向“探究”，以黄河为母体建立跨学科STEAM学习系统，馆校共创，实现展教同场、情境化体验与深度动手实践。",
  "signature_activities": [
    {
      "name": "黄河之光·水动力光学科学秀",
      "format": "中庭/门厅舞台化演示，融合光影与水力学实验（如：水膜波纹、激光水幕、水流发电演示）",
      "spatial_requirement": "8-12米高中庭，设置可升降演示台与投影.mapping；上缘设滑轮/吊点；地面防水与排水；舞台背投墙与吊点额定≥1.0 kN。"
    },
    {
      "name": "黄河实验室（玻璃盒子）",
      "format": "展厅内开放式实验工坊，围绕水的物理/化学特性（流体力学、溶解与导电、表面张力）",
      "spatial_requirement": "玻璃隔断展间面积80-120㎡，局部半围合工位；通风≥6次/小时；备洗眼器与灭火沙；地面荷载≥3.5 kN/㎡，独立电气与中水供水。"
    },
    {
      "name": "科学与河共生讲坛",
      "format": "专家/院士讲座，配合河岸生态、气象、水文数据可视化墙",
      "spatial_requirement": "40座阶梯式讲座室，面积60-80㎡；固定声学与LED信息墙；后排观演高度差≥0.12 m；预留网络与直播端口。"
    },
    {
      "name": "黄河之夜·科学露营",
      "format": "夜间天文观测与水环境夜话，配合河岸夜航与沉浸式光影剧场",
      "spatial_requirement": "顶层观星露台≥200㎡，遮光窗帘与围栏高度1.2 m；可升降遮光幕；设2个独立疏散通道；夜间临时展馆开放走道。"
    },
    {
      "name": "黄河生态工作坊",
      "format": "水质检测、显微观察、DNA/微生物启蒙、小型水生生态缸搭建",
      "spatial_requirement": "生物实验室90-120㎡，2套生物安全柜；显微镜台10位；展示水族系统与过滤；上下水点位密度≥2个/10㎡。"
    },
    {
      "name": "河力学探索吧",
      "format": "互动装置与基础力学实验（浮力、伯努利、水轮机、泵站模型），鼓励团队解题",
      "spatial_requirement": "开放式工作坊120㎡，地面可移动小展台；墙体内埋水电接口；模块化座椅与工位；储物柜≥6组。"
    },
    {
      "name": "水旅程沉浸剧场",
      "format": "多感官体验装置，模拟黄河从青藏高原到入海的路径与环境变化",
      "spatial_requirement": "暗室40-60㎡，内设环形步道与地面互动投影；通风≥4次/小时；无障碍坡度≤1:20；疏散指示清晰。"
    },
    {
      "name": "黄河溯源科学追光队",
      "format": "馆校合作的跨学科研学营，结合黄河文化与科技创新主题",
      "spatial_requirement": "多功能教室两间（各80㎡）可拼接；移动讲台与分组工位；壁挂式教学系统；可实现分时错峰使用。"
    },
    {
      "name": "流动科技站（科普大篷车）",
      "format": "巡展车进校进社区，开展水与科技主题微课堂与实验演示",
      "spatial_requirement": "载重≥5吨车辆停靠位与地面加固；车辆外接电源380V/63A；室外遮雨棚≥25㎡；人员安全缓冲带。"
    },
    {
      "name": "好奇玩家·科学与茶点",
      "format": "轻食科学社交空间，提供气泡水科学实验与饮品安全科普",
      "spatial_requirement": "咖啡吧台25㎡，设净水/中水制备台；台下洗消槽与垃圾分类；地面防滑；通风≥3次/小时；噪声≤55 dB。"
    }
  ],
  "spatial_integration": {
    "embedded_labs": "在“水与自然”“力学与能量”展区内设置2-3个玻璃盒子实验区，面积80-120㎡，采用通高玻璃与可开启安全窗，配套局部负压与独立排风（上置与桌面排风）；地面留出开放工位与演示岛，台面模块化可更换；展示区与观众动线为线性穿越，形成“看得见的实验室”，展教人员可在内部进行演示，观众在外圈观演与分区互动，避免拥堵与气味扩散。"
  },
  "public_performance": "利用主中庭与次中庭设置可移动舞台模块与观众看台，中庭挑高≥8米，预留吊点与滑轮系统用于水光学、激光与水幕表演；舞台后方为临时“道具与安全角”，侧向设应急洗眼与消防砂箱；两侧大台阶作为“坐看台”，采取分层布置，台阶宽度≥1.2米，荷载≥3.5 kN/㎡；门厅与展馆首层之间设置伸缩围栏与标识系统，与日常流线形成软隔离，保证科学秀时段的安全与通行。"
  },
  "dedicated_education_zone": {
    "room_configuration": "独立教育区总面积约680-750㎡，配置如下：通用教室4间（每间60-80㎡）、物理实验室90㎡、化学实验室110㎡（设3台1200mm通风橱与2台洗眼器）、生物实验室100㎡（2台生物安全柜）、机器人与程序工作室100㎡、创客工坊120㎡、器材与药品准备间20㎡、洗消与废弃处理8㎡、教师休息与办公室24㎡、储物柜间6㎡；各房间电气按实验要求预留380V/220V与独立接地，通风按房间功能匹配（普通教室≥3次/小时，化学≥6次/小时，生物≥8次/小时），噪声控制≤55 dB（除机械风噪与通风外）。",
    "zoning_strategy": "建议布置于二层黄河展线末端，靠近研学交通电梯与专用货梯，形成“展—学—教”的纵向闭环；设首层独立门禁入口与安检通道，支持周末与夜间独立开放；与普通观众动线互不交叉，设置单向通行与安全隔离带；在关键节点部署智能导引与时隙预约系统，实现研学团队快速到离场与实时控流。"
  }
}
